"""Four original-frame RGB sources for the one-way-to-two-way turn delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer actual curb/centerline visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 95),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-3.0, 2.5, 2.6), (-7.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans(overview_height_delta_m=0.0):
    if not 0.0<=overview_height_delta_m<=2.0:
        raise ValueError('Unsupported overview mount change')
    result=[]
    for name,spec in CAMERAS.items():
        location,rotation,size,fov=spec
        if name=='overview':
            location=(location[0],location[1],location[2]+overview_height_delta_m)
        result.append(CameraPlan(name,location,rotation,size,fov))
    return result


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class TurnCameraCapture:
    def __init__(self, world, carla_module, subject, sinks, overview_height_delta_m=0.0):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans(overview_height_delta_m):
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Original-footprint observations for NRS 484B.400(4); no legal cutoff."""
from __future__ import annotations
from math import hypot
import json
from pathlib import Path

def _load(p):
    p=Path(p)
    if not p.is_file(): raise ValueError("missing required geometry source: "+str(p))
    return json.loads(p.read_text())

def _line(points):
    if not isinstance(points,list) or len(points)!=2: raise ValueError("line needs two original map points")
    a,b=points
    if any(type(v) not in (int,float) for p in points for v in p) or len(a)!=2 or len(b)!=2:
        raise ValueError("invalid map point")
    dx,dy=b[0]-a[0],b[1]-a[1]
    length=hypot(dx,dy)
    if length < 1: raise ValueError("degenerate map reference line")
    return a,dx,dy,length

def _signed(point,line):
    a,dx,dy,length=line
    return (dx*(point[1]-a[1])-dy*(point[0]-a[0]))/length

def measure(geometry_path, body_path):
    g,b=_load(geometry_path),_load(body_path)
    if g.get("source_directionality")!="one_way" or g.get("destination_directionality")!="two_directional":
        raise ValueError("exact one-way-to-two-directional layout missing")
    if g.get("maneuver")!="left_turn" or not g.get("intersection_id") or not g.get("map_source"):
        raise ValueError("turn or map-source provenance missing")
    curb=_line(g.get("source_left_curb")); center=_line(g.get("destination_centerline"))
    rows=b.get("frames")
    if not isinstance(rows,list) or not rows: raise ValueError("original body footprint frames missing")
    indices=[r.get("frame") for r in rows]
    if any(type(i) is not int for i in indices) or indices!=sorted(set(indices)):
        raise ValueError("body frame identities unordered or repeated")
    if not b.get("subject_id") or any(r.get("subject_id")!=b["subject_id"] for r in rows):
        raise ValueError("body footprint subject mismatch")
    approach=[r for r in rows if r.get("phase")=="approach"]
    departure=[r for r in rows if r.get("phase")=="leaving_intersection"]
    if not approach or not departure or approach[-1]["frame"]>=departure[0]["frame"]:
        raise ValueError("approach and leaving-intersection phases absent or reversed")
    def corners(row):
        p=row.get("ground_corners")
        if not isinstance(p,list) or len(p)!=4 or any(not isinstance(x,list) or len(x)!=2 or any(type(v) not in (int,float) for v in x) for x in p):
            raise ValueError("four original ground body corners required")
        return p
    approach_curb=[abs(_signed(p,curb)) for r in approach for p in corners(r)]
    # Positive is left of directed centerline; negative is right. Direction is the entered road's travel direction.
    departure_side=[_signed(p,center) for r in departure for p in corners(r)]
    return {"subject_id":b["subject_id"],"intersection_id":g["intersection_id"],
            "source_directionality":"one_way","destination_directionality":"two_directional",
            "maneuver":"left_turn","approach_left_curb_nearest_m":min(approach_curb),
            "approach_left_curb_farthest_m":max(approach_curb),
            "departure_centerline_min_signed_m":min(departure_side),
            "departure_centerline_max_signed_m":max(departure_side),
            "departure_all_corners_right_of_centerline":max(departure_side)<0,
            "approach_frame_ids":[r["frame"] for r in approach],
            "departure_frame_ids":[r["frame"] for r in departure],
            "source_refs":[str(geometry_path),str(body_path)],"legal_conclusion":None}

def main():
    import argparse
    ap=argparse.ArgumentParser()
    ap.add_argument("--geometry",required=True);ap.add_argument("--body",required=True);ap.add_argument("--output",required=True)
    a=ap.parse_args();Path(a.output).write_text(json.dumps(measure(a.geometry,a.body),indent=2)+"\n")
if __name__=="__main__":main()

"""Independent comparison of measured approach and departure positions."""
import json
from pathlib import Path

def audit(paths,variable):
    if variable not in ("approach_curb_position","departure_centerline_side"):
        raise ValueError("unknown comparison variable")
    if len(paths)!=2: raise ValueError("comparison needs two exact cases")
    rows=[json.loads(Path(p).read_text()) for p in paths]
    for r in rows:
        if len(r.get("source_refs",[]))!=2 or r.get("legal_conclusion") is not None:
            raise ValueError("source-bound measurement missing or legal conclusion asserted")
    for key in ("subject_id","intersection_id","source_directionality","destination_directionality","maneuver"):
        if rows[0].get(key)!=rows[1].get(key): raise ValueError("fixed geometry or identity changed: "+key)
    if variable=="approach_curb_position":
        if rows[0].get("departure_all_corners_right_of_centerline")!=rows[1].get("departure_all_corners_right_of_centerline"):
            raise ValueError("held departure side changed")
        for bound in ("departure_centerline_min_signed_m", "departure_centerline_max_signed_m"):
            if abs(rows[0][bound]-rows[1][bound])>0.001:
                raise ValueError("held departure position changed: "+bound)
        key="approach_left_curb_nearest_m"
    else:
        for bound in ("approach_left_curb_nearest_m", "approach_left_curb_farthest_m"):
            if abs(rows[0][bound]-rows[1][bound])>0.001:
                raise ValueError("held approach curb position changed: "+bound)
        key="departure_centerline_max_signed_m"
    if abs(rows[0][key]-rows[1][key])<0.001:
        raise ValueError("deliberate measured position did not vary")
    return {"comparison_complete":True,"variable":variable,"fixed_conditions_checked":["subject_id","intersection_id","directionalities","maneuver","held other position"],"legal_conclusion":None}

